namespace AlarmHub.Contracts.DeviceEvents;

/// <summary>
/// Integration event published by the ingest service after a panel event was accepted and persisted.
/// </summary>
/// <remarks>
/// Contract rules:
/// <list type="bullet">
/// <item><description><see cref="EventId"/> is generated by the panel (or by ingest when the panel has none)
/// and is the idempotency key for every downstream consumer.</description></item>
/// <item><description><see cref="SequenceNumber"/> is monotonically increasing per panel; it lets consumers
/// detect gaps and out-of-order delivery.</description></item>
/// <item><description>Properties are additive only. Removing or renaming a property requires a V2 contract.</description></item>
/// </list>
/// </remarks>
/// <param name="EventId">Idempotency key of the event; downstream services must process it at most once.</param>
/// <param name="PanelId">Identifier of the alarm panel that produced the event.</param>
/// <param name="OccurredAt">Moment the panel recorded the event, in UTC.</param>
/// <param name="Type">Kind of the event.</param>
/// <param name="SequenceNumber">Per-panel sequence number used to detect gaps and reordering.</param>
/// <param name="Payload">Raw key/value attributes reported by the panel (zone, battery level, ...).</param>
/// <param name="ReceivedAt">Moment ingest accepted the event; used to measure ingestion latency.</param>
public sealed record DeviceEventReceivedV1(
    Guid EventId,
    Guid PanelId,
    DateTimeOffset OccurredAt,
    DeviceEventType Type,
    long SequenceNumber,
    IReadOnlyDictionary<string, string> Payload,
    DateTimeOffset ReceivedAt);
